function _insAntes(id, titulo, blocos){ var f=S[id].fundo, k=-1; for (var n=0;n<f.length;n++){ if(f[n][0]==='h' && f[n][1]===titulo){k=n;break;} } if(k<0) k=f.length; S[id].fundo = f.slice(0,k).concat(blocos, f.slice(k)); }
